/bin/zsh -lc "rtk python3 -c 'import json; from pathlib import Path; root=Path(\".codex-check-evidence-4c2f048/release-path-checkout/QA/CHG-232/release\");
def scan(x,path=\"\"):
 if isinstance(x,dict):
  if \"findings\" in x or \"artifact_secret_scan\" in path or \"artifact_scan\" in path:
   f=x.get(\"findings\")
   print(path or \"/\", \"status=\", x.get(\"status\"), \"findings=\", len(f) if isinstance(f,list) else f, \"keys=\", sorted(x.keys()))
  for k,v in x.items(): scan(v, f\"{path}.{k}\" if path else k)
 elif isinstance(x,list):
  for i,v in enumerate(x): scan(v, f\"{path}[{i}]\")
for name in (\"pages-release.log\",\"pages-verify-public.log\"):
 p=root/name
 rows=[line for line in p.read_text().splitlines() if line.lstrip().startswith(\"{\") and \"status\" in line]
 obj=json.loads(rows[-1])
 public=obj.get(\"public\",obj)
 print(name, \"top_status=\", obj.get(\"status\"), \"public_status=\", public.get(\"status\"), \"revision=\", obj.get(\"candidate_head\",public.get(\"revision\")))
 print(\"checks=\", public.get(\"checks\"))
 sec=public.get(\"security_privacy\",{})
 print(\"security_status=\",sec.get(\"status\"), \"security_keys=\", sorted(sec.keys()))
 scan(sec, \"security_privacy\")
q=json.loads((root/\"qualification.json\").read_text())
print(\"qualification=\",q.get(\"status\"),q.get(\"candidate_head\"),\"tests=\",len(q.get(\"tests\",[])))
log=Path(\".codex-check-evidence-4c2f048/QA/CHG-232/release/unit-tests.log\").read_text()
print(\"unit_summary=\",[line.strip() for line in log.splitlines() if line.startswith(\"Ran \") or line.strip()==\"OK\"][-2:])'"
